// The built-in ingredient guide: what is commonly sold as a vitamin, supplement or pre-workout
// in the United States and Canada, what it is for, how good the evidence is, and the numbers the
// stack check compares against.
//
// Sources (general, not per line): the US/Canada Dietary Reference Intakes (National Academies)
// as published in the NIH Office of Dietary Supplements fact sheets, for `rda` and vitamin and
// mineral `max` values; FDA and Health Canada guidance for caffeine, synephrine, green tea
// extract and the flagged ingredients; International Society of Sports Nutrition position
// stands for the `dose` ranges of performance ingredients.
//
// This is general information for healthy adults, not medical advice. Values are for adults
// 19 to 50 who are not pregnant.
// ponytail: one adult reference set. Add age bands and pregnancy when the app has a profile for it.

export type Unit = "mcg" | "mg" | "g" | "IU" | "billion CFU";
export type Evidence = "strong" | "moderate" | "weak" | "none";
export type Category =
  | "vitamin" | "mineral" | "fat" | "protein" | "performance" | "stimulant" | "focus"
  | "sleep" | "herb" | "joint" | "gut" | "general" | "hormone" | "flagged";

export interface Ingredient {
  id: string;
  name: string;
  /** other names seen on labels, lower case */
  aka?: string[];
  cat: Category;
  /** the unit `rda`, `max` and `dose` are written in */
  unit: Exclude<Unit, "IU">;
  /** how much of `unit` one IU is, where labels still use IU */
  iu?: number;
  /** recommended daily intake from all sources: one number, or [men, women] */
  rda?: number | [number, number];
  /** daily ceiling: the DRI upper limit (from supplements where the DRI says so) or regulator guidance */
  max?: number;
  /** daily range used in the studies that found a benefit */
  dose?: [number, number];
  benefit: string;
  evidence: Evidence;
  caution?: string;
  /** a stimulant: counted together in the stack check */
  stim?: boolean;
  /** North American diets commonly fall short of this one */
  short?: boolean;
  /** a regulator has acted against this ingredient in supplements */
  flag?: string;
}

