const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

const INDEX = new Map<string, Ingredient>();
for (const i of KB) for (const n of [i.name, i.id, ...(i.aka ?? [])]) INDEX.set(norm(n), i);

/** The guide entry for a name as written on a label, or undefined. */
export function findIngredient(label: string): Ingredient | undefined {
  const n = norm(label);
  if (!n) return undefined;
  // exact name or alias first, then the label with a trailing "(as …)" or "extract" removed
  return INDEX.get(n) ?? INDEX.get(norm(label.replace(/\(.*?\)/g, ""))) ?? INDEX.get(n.replace(/ (extract|powder|hcl)$/, ""));
}

export const byId = (id: string) => KB.find((i) => i.id === id);
